/**
 * Example using acme-retry to handle flaky functions
 *
 * This example shows how to retry a function that might fail, with exponential backoff.
 */

const { retry } = require('./node_modules/acme-retry');

// Create a flaky function that might fail
// Let's make it fail on odd numbers, succeed on even numbers
function flakyService(requestNumber) {
  console.log(`🔄 Attempt ${requestNumber}...`);
  return new Promise((resolve, reject) => {
    // Simulate failure 50% of the time
    if (requestNumber % 2 !== 0) {
      const error = new Error(`Failed on attempt ${requestNumber} - network glitch!`);
      console.log(` ❌ Failed! Will retry...`);
      reject(error);
    } else {
      console.log(` ✅ Success on attempt ${requestNumber}!`);
      resolve({ data: `Processed request #${requestNumber}`, status: 'ok' });
    }
  });
}

// Create a wrapper function that always starts from 1
const callFlakyService = async (numAttempts) => {
  try {
    const result = await retry(
      () => flakyService(numAttempts),
      { attempts: 5, baseMs: 100 }
    );
    console.log(`🏁 Final result:`, result);
    return result;
  } catch (error) {
    console.log(`💥 All attempts failed after 5 retries:`, error.message);
    throw error;
  }
};

// Main execution
async function main() {
  console.log('🎮 Starting retry example...\n');
  console.log('Configuration: 5 maximum attempts, 100ms base delay\n');

  try {
    const result = await callFlakyService(1);
    console.log(`\n✅ Operation completed successfully after retries!`);
  } catch (error) {
    console.log(`\n❌ Operation ultimately failed.`);
  }

  console.log('\n--- Another run to show success faster ---\n');
  try {
    const result = await callFlakyService(2);
    console.log(`\n✅ Operation completed successfully after retries!`);
  } catch (error) {
    console.log(`\n❌ Operation ultimately failed.`);
  }
}

main();

