/**
 * Simulates a flaky external API call that might fail
 */
async function flakyApiCall(data, retryNumber) {
  console.log(`   🔗 Attempt ${retryNumber}: Calling API...`);

  // Randomly fail (for demo purposes)
  const shouldFail = Math.random() > 0.5;

  if (shouldFail) {
    console.log(`      ❌ API request failed (network timeout)`);
    throw new Error('Network timeout');
  }

  console.log(`      ✅ API request succeeded`);
  return { success: true, data };
}

/**
 * Execute the flaky API call with retry logic
 */
async function callApiWithRetry(data) {
  console.log(`🚀 Sending data: ${JSON.stringify(data)}`);

  const result = await retry(
    () => flakyApiCall(data, 1),
    {
      attempts: 5,        // Maximum retry attempts (total tries = 1 + 4)
      baseMs: 100         // Base delay in milliseconds
    }
  );

  console.log(`✅ Service responded: ${JSON.stringify(result)}`);
  return result;
}

// Demo 1: Success after retry
async function demo1() {
  console.log('=\n= DEMO 1: API eventually succeeds\n=\n');
  await callApiWithRetry({ userId: 123, action: 'login' });
}

// Demo 2: Fail after all retries
async function demo2() {
  console.log('\n=\n= DEMO 2: API fails after all retries\n=\n');
  // Set up to always fail
  const failingRetry = async () => {
    console.log(`   🔗 Attempt 1: API call (designed to fail)`);
    throw new Error('Permanent error: service down');
  };

  try {
    await retry(failingRetry, { attempts: 5 });
  } catch (error) {
    console.log(`💥 All attempts exhausted: ${error.message}`);
  }
}

// Run demos
(async () => {
  await demo1();
  await demo2();
