/**
 * Example demonstrating the acme-retry package
 *
 * This example shows how to retry a flaky function with exponential backoff.
 *
 * API:
 *   retry(fn, opts) - Retry function with options
 *   where:
 *     fn: Async function to retry (must return a Promise)
 *     opts.attempts: Number of tries (default: 3)
 *     opts.baseMs: Base delay in milliseconds (default: 100)
 *     opts.maxMs: Maximum delay between retries (default: no limit)
 *
 * How it works:
 *   - Calls your function
 *   - If it fails, waits with exponential backoff (baseMs * 2^i where i is attempt number)
 *   - Retries up to 'attempts' times
 *   - If all attempts fail, throws the last error
 */

// Simulate a flaky function that mostly works but sometimes fails
async function flakyOperation() {
  // Simulate random success/failure
  const shouldFail = Math.random() < 0.3; // 30% chance of failure

  if (shouldFail) {
    console.log('  ❌ Operation failed!');
    throw new Error('Random failure occurred');
  }

  console.log('  ✅ Operation succeeded!');
  return 'Success!';
}

// Example 1: Basic usage with default settings (3 attempts, 100ms base delay)
async function example1() {
  console.log('\n=== Example 1: Basic usage (3 attempts, 100ms base delay) ===');
  try {
    const result = await retry(flakyOperation, { attempts: 3, baseMs: 100 });
    console.log('Result:', result);
  } catch (error) {
    console.log('Final error:', error.message);
  }
}

