  console.log('\n=== Example 2: 5 attempts with 500ms base delay ===');
  try {
    const result = await retry(flakyOperation, { attempts: 5, baseMs: 500 });
    console.log('Result:', result);
  } catch (error) {
    console.log('Final error:', error.message);
  }
}

