      baseMs: 100  // Initial delay in milliseconds
    });
    console.log(`\nFinal result: ${result}`);
  } catch (error) {
    console.log(`\n❌ All attempts failed after 5 retries`);
    console.log(`Last error: ${error.message}`);
  }
})();
